-- Generated by `drizzle-kit generate`, then HAND-EDITED: `IF NOT EXISTS` so a
-- re-run of a file whose journal entry did not land is a no-op (migrations are
-- applied BY HAND; see 0015). Invisible to drizzle-kit, so
-- meta/0018_snapshot.json matches lib/db/schema.ts exactly.
--
-- Plain CREATE INDEX, not CONCURRENTLY: drizzle's migrator runs pending
-- migrations in one transaction, where CONCURRENTLY is an error. The table is
-- small, so the brief write lock is immaterial.
--
-- ROLLBACK: `DROP INDEX IF EXISTS "submissions_discovered_by_idx";` is safe at
-- any time (no code depends on the index existing); also delete this
-- migration's row from `drizzle.__drizzle_migrations`.
CREATE INDEX IF NOT EXISTS "submissions_discovered_by_idx" ON "submissions" USING btree (("provenance" ->> 'discoveredBy'));
